SECRETARY_BODY = '县委小楼二楼，门虚掩着。他在桌前坐着，没戴老花镜。桌上摊着的是巡察组的进驻通知，纸的边角卷了。\n\n他没让你坐。\n\n蒋崇岳：「昨天下午会议室那一出，我听说了。」\n\n他抬眼看你。\n\n蒋崇岳：「致远，我不问你是怎么想的。我只讲一个道理。巡察组半个月就走，赵建国要在云溪待到退休，你要在云溪至少待三年。你算算这个账。」\n\n他把通知推到一边。\n\n蒋崇岳：「柳林村那个数，年底之前必须够。这半个月你要是把班子搅散了，剩下的日子你一户也签不下来。」\n\n他这才让你坐。\n\n蒋崇岳：「我不是拦你查。我是告诉你，你要动谁，得先掂量掂量你动得动。」\n\n他端起茶杯，喝了一口，放下。\n\n蒋崇岳：「还有一句。宏达那个项目是市里挂号的。你要碰它，先来跟我说。别让我从别人嘴里听见。」'
SECRETARY_VISIT = "第三十三日，你来到县委小楼。" + "\n\n" + SECRETARY_BODY.replace("昨天下午会议室那一出，我听说了。", "昨天下午查账的事，我听说了。")
SECRETARY_SUMMONS = "第三十四日上午，县长办公会前，蒋崇岳叫你到县委小楼。" + "\n\n" + SECRETARY_BODY.replace("昨天下午会议室那一出，我听说了。", "前天下午查账的事，我听说了。")

def secretary_visits(session):
    return [log for log in session.logs if log.get("type") == "conversation_started"
            and log.get("story_day") == 33 and log.get("opportunity_id") == "opp_33_jiang_chongyue_contact"]

def secretary_opportunity(opportunity, session, *, starting=False):
    if session.package_id != "pkg_gameplay_v3" or session.game_state.story_day != 33 or opportunity.opportunity_id != "opp_33_jiang_chongyue_contact":
        return opportunity
    visits = secretary_visits(session)
    active = session.active_conversation
    if (starting and not visits) or (not starting and visits and active and visits[0].get("conversation_id") == active.conversation_id):
        return replace(opportunity, opening_narrative=SECRETARY_VISIT)
    return opportunity

def secretary_fallback(session):
    if session.package_id != "pkg_gameplay_v3" or session.game_state.story_day != 34 or secretary_visits(session):
        return ()
    paragraphs = SECRETARY_SUMMONS.split("\n\n")
    return tuple(NarrativeBlock(block_id=f"d34_secretary_summons_{n}", kind="narration",
        text="\n\n".join(paragraphs[i:i+4]), scene_id="C01_S04", presentation_phase="scene")
        for n,i in enumerate(range(0,len(paragraphs),4),1))

def restore_round_two(block, session):
    if session.package_id != "pkg_gameplay_v3":
        return block
    text = ROUND_TWO_PROSE.get(block.block_id)
    if text is not None:
        return replace(block, text=text, kind="narration", speaker=None)
    # Legacy saves have no separately inserted summons. Project it before the meeting.
    if block.block_id == "d34_meeting" and not secretary_visits(session) and not any(
        x.block_id == "d34_secretary_summons_1" for x in session.narrative_feed):
        return replace(block, text=SECRETARY_SUMMONS+"\n\n"+block.text, kind="narration", speaker=None)
    if getattr(block,"story_day",None) == 33 and block.kind == "conversation_opening" and block.speaker == "蒋崇岳":
        first = next((x for x in session.narrative_feed if x.story_day == 33 and x.kind == "conversation_opening" and x.speaker == "蒋崇岳"),None)
        if first and first.cursor == block.cursor:
            return replace(block,text=SECRETARY_VISIT)
    return block
